import json
from pathlib import Path
from same_day_1445.live_optimizer.engine.orchestrator import run_optimizer

def test_optimizer_persists_latest_and_immutable_decision_artifact(tmp_path: Path):
    root=tmp_path/'opt';(root/'config').mkdir(parents=True);(root/'ledger').mkdir();(root/'state').mkdir();cfg={'mode':'SHADOW_ONLY','cooldown_days':0,'gates':{'trigger_retention_min':0.9,'win_rate_delta_min':0.005,'mean_return_delta_min':0.0,'max_drawdown_deterioration_max':0.01,'recent_windows_improve_fraction_min':0.0,'recent_window_win_rate_regression_max':1.0,'neighbor_pass_rate_min':0.0,'minimum_evaluation_windows':0},'drift':{},'lines':{x:{'minimum_new_samples':0,'minimum_regimes':0,'accounting':'research_sum' if x=='D' else 'compound'} for x in 'CSDR'},'candidate_spaces':{},'evaluation_windows':[]};(root/'config/optimizer.json').write_text(json.dumps(cfg),encoding='utf-8');result=run_optimizer(root,'2026-08-24T15:20:00+08:00');latest=json.loads((root/'state/latest_optimizer_decision.json').read_text(encoding='utf-8'));assert latest['decision_hash']==result['decision_hash'];immutable=root/'ledger/optimizer_decisions'/f"{result['decision_hash']}.json";assert immutable.exists();before=immutable.read_bytes();result2=run_optimizer(root,'2026-08-24T15:20:00+08:00');assert result2['decision_hash']==result['decision_hash'];assert immutable.read_bytes()==before
